import { chat } from "@voxta";
export function trigger(e) {
    const prompt = String(e.arguments.prompt || '').trim();
    let style = String(e.arguments.style || '').trim();
    // a style only makes sense for these; the model tends to add 'sexy' to everything
    if (!/danc|walk|wave|waving|stroll|march/i.test(prompt)) style = '';
    const text = (style && prompt.toLowerCase().indexOf(style.toLowerCase()) < 0) ? (prompt + ' ' + style).trim() : prompt;
    if (!text) return;
    chat.appTrigger('Bool', 'Person', 'geometry', 'useAdvancedColliders', false);
    chat.appTrigger('String', 'Person', 'plugin#2_ElkVR.BVHPlayer', 'Motion Request', text);
}

import { chat } from "@voxta";

const PLUGIN = 'plugin#4_Bplus.SmartWardrobe';
const PARTS = {
  all: 'All', top: 'Top', shirt: 'Top', jacket: 'Top', blouse: 'Top',
  bottom: 'Bottom', pants: 'Bottom', skirt: 'Bottom', shorts: 'Bottom', jeans: 'Bottom',
  bra: 'Bra', panties: 'Panties', underwear: 'Panties', thong: 'Panties',
  dress: 'Dress', shoes: 'Shoes', boots: 'Shoes', heels: 'Shoes', socks: 'Socks',
  stockings: 'Stockings', tights: 'Stockings', accessory: 'Accessory', accessories: 'Accessory'
};
const words = s => String(s || '').toLowerCase().replace(/[^a-z]+/g, ' ').split(' ').filter(w => w);
const pickPart = ws => { for (const w of ws) if (PARTS[w]) return PARTS[w]; return null; };

export function trigger(e) {
  const stateWords = words(e.arguments.state);
  let state = null;
  if (stateWords.some(w => w === 'undress' || w === 'off' || w === 'remove')) state = 'Undress';
  else if (stateWords.some(w => w === 'dress' || w === 'on')) state = 'Dress';
  if (!state) {
    console.log('set_clothing: could not read state "' + e.arguments.state + '", ignored');
    return;
  }
  // "dress" in the state text is the verb, not the Dress category
  const part = pickPart(words(e.arguments.part)) || pickPart(stateWords.filter(w => w !== 'dress'));
  chat.appTrigger('StringChooser', 'Person', PLUGIN, (part || 'All') + ' Control', state);
}

import { chat } from "@voxta";

// Exactly as the SmartWardrobe "Change Outfit" dropdown shows them. Add the rest of your presets.
const OUTFITS = ['Fully_dressed', 'Lewd_A', 'lewd_B', 'Fulley_lewd', 'Nude_A'];
const clean = s => String(s || '').trim().toLowerCase().replace(/\.vap$/, '').replace(/^preset_/, '');

export function trigger(e) {
  const match = OUTFITS.find(o => clean(o) === clean(e.arguments.outfit));
  if (!match) {
    console.log('change_outfit: unknown outfit "' + e.arguments.outfit + '", ignored');
    return;
  }
  chat.appTrigger('StringChooser', 'Person', 'plugin#4_Bplus.SmartWardrobe', 'All Control', 'Dress');
  chat.appTrigger('StringChooser', 'Person', 'plugin#4_Bplus.SmartWardrobe', 'Change Outfit', match);
}
